import React, { memo, useCallback, useDeferredValue, useEffect, useMemo, useState } from 'react';
import { Alert, FlatList, InteractionManager, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';
import { refreshBluecoinsSummary, type BluecoinsSummary } from '../services/bluecoins';
import {
  applyEntryBalance, confirmRedCoinsExport, exportRedCoinsBackup, exportRedCoinsCsv, loadRedCoins, saveRedCoins,
  type RedCoinsAccountType, type RedCoinsEntry, type RedCoinsState, type RedCoinsType,
} from '../services/redcoins';

const C = { ink: '#111A2A', paper: '#FFF9EA', cream: '#F0E6D4', coral: '#F04444', mint: '#83D8B4', blue: '#528FF2', muted: '#7C8290', white: '#FFFFFF', gold: '#E7B84A' };
const money = (n = 0) => `RM ${Math.abs(n).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const dayKey = (value: string) => value.slice(0, 10);
type Section = 'home' | 'activity' | 'accounts' | 'plan' | 'reports';

export default function RedCoinsScreen({ navigation, route }: any) {
  const [state, setState] = useState<RedCoinsState | null>(null);
  const [bluecoins, setBluecoins] = useState<BluecoinsSummary | null>(null);
  const [section, setSection] = useState<Section>('home');
  const [entryOpen, setEntryOpen] = useState(false);
  const [manageOpen, setManageOpen] = useState<'account' | 'category' | 'sub' | null>(null);
  const [search, setSearch] = useState('');
  const [filterOpen, setFilterOpen] = useState(false);
  const [filterType, setFilterType] = useState<'all' | RedCoinsType>('all');
  const [filterAccount, setFilterAccount] = useState('all');
  const [filterCategory, setFilterCategory] = useState('all');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [item, setItem] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<RedCoinsType>('expense');
  const [account, setAccount] = useState('');
  const [toAccount, setToAccount] = useState('');
  const [category, setCategory] = useState('');
  const [subcategory, setSubcategory] = useState('');
  const [note, setNote] = useState('');
  const [labels, setLabels] = useState('');
  const [repeat, setRepeat] = useState<RedCoinsEntry['repeat']>('none');
  const [installments, setInstallments] = useState('');
  const [advanced, setAdvanced] = useState(false);
  const [draftName, setDraftName] = useState('');
  const [draftType, setDraftType] = useState<RedCoinsAccountType>('Bank');
  const [draftBalance, setDraftBalance] = useState('0');
  const [draftCategory, setDraftCategory] = useState('');
  const [draftSub, setDraftSub] = useState('');
  const [draftParent, setDraftParent] = useState('');
  const deferredSearch = useDeferredValue(search);

  useEffect(() => {
    (async () => {
      let summary: BluecoinsSummary | null = null;
      try { summary = await refreshBluecoinsSummary(); setBluecoins(summary); } catch {}
      const loaded = await loadRedCoins(summary);
      setState(loaded);
    })();
  }, []);

  useEffect(() => {
    const mode = route?.params?.mode;
    if (!state || !['expense', 'income', 'transfer'].includes(mode)) return;
    resetEntry();
    setType(mode as RedCoinsType);
    navigation.setParams({ mode: undefined });
  }, [route?.params?.mode, state?.createdAt]);

  const persist = async (next: RedCoinsState) => { setState({ ...next }); await saveRedCoins(next); };
  const resetEntry = () => {
    if (!state) return;
    setItem(''); setAmount(''); setType('expense'); setAccount(state.accounts.find((a) => a.type === 'Credit card')?.name || state.accounts[0]?.name || '');
    setToAccount(''); setCategory(state.categories[0]?.name || 'General'); setSubcategory(state.categories[0]?.subcategories[0] || 'General');
    setNote(''); setLabels(''); setRepeat('none'); setInstallments(''); setAdvanced(false); setEntryOpen(true);
  };
  const suggestions = useMemo(() => {
    if (!item.trim()) return [];
    const own = state?.entries.filter((e, i, all) => e.item.toLowerCase().includes(item.toLowerCase()) && all.findIndex((x) => x.item.toLowerCase() === e.item.toLowerCase()) === i) || [];
    const imported = bluecoins?.monthly.fixedCommitmentOptions.filter((x) => x.label.toLowerCase().includes(item.toLowerCase())).slice(0, 5).map((x, i) => ({ id: `blue-${i}`, item: x.label.split(' | ').pop() || x.label, amount: x.amount, account: '', category: x.category, subcategory: x.label.split(' | ')[0] || x.category, type: 'expense' as const, date: '', labels: [] })) || [];
    return [...own, ...imported].slice(0, 6);
  }, [item, state?.entries, bluecoins]);
  const chooseSuggestion = (entry: any) => { setItem(entry.item); if (entry.amount) setAmount(String(entry.amount)); if (entry.account) setAccount(entry.account); setCategory(entry.category); setSubcategory(entry.subcategory); };
  const saveEntry = async () => {
    if (!state || !item.trim() || !Number(amount) || !account || (type === 'transfer' && !toAccount)) return Alert.alert('Incomplete entry', 'Add item, amount and account first.');
    const entry: RedCoinsEntry = { id: `${Date.now()}`, item: item.trim(), amount: Number(amount), type, account, toAccount: type === 'transfer' ? toAccount : undefined, category: type === 'transfer' ? '(Transfer)' : category, subcategory: type === 'transfer' ? '(Transfer)' : subcategory, date: new Date().toISOString(), note: note.trim(), labels: labels.split(',').map((x) => x.trim()).filter(Boolean), status: 'cleared', repeat, installments: Number(installments) || undefined, origin: 'redcoins' };
    const next = { ...state, entries: [entry, ...state.entries], accounts: state.accounts.map((a) => ({ ...a })) };
    applyEntryBalance(next, entry, 1);
    setEntryOpen(false);
    setSection('activity');
    setState(next);
    InteractionManager.runAfterInteractions(() => {
      saveRedCoins(next).catch(() => Alert.alert('Save failed', 'The transaction is still visible, but LeanLog could not write it to local storage. Please try again.'));
    });
  };
  const removeEntry = (entry: RedCoinsEntry) => Alert.alert('Move to Trash?', entry.item, [{ text: 'Cancel' }, { text: 'Move', style: 'destructive', onPress: async () => { if (!state) return; const next = { ...state, entries: state.entries.filter((e) => e.id !== entry.id), trash: [entry, ...state.trash], accounts: state.accounts.map((a) => ({ ...a })) }; applyEntryBalance(next, entry, -1); await persist(next); } }]);

  const filtered = useMemo(() => {
    if (!state) return [];
    const needle = deferredSearch.trim().toLowerCase();
    return state.entries.filter((entry) => {
      if (filterType !== 'all' && entry.type !== filterType) return false;
      if (filterAccount !== 'all' && entry.account !== filterAccount) return false;
      if (filterCategory !== 'all' && entry.category !== filterCategory) return false;
      if (!needle) return true;
      return `${entry.item}\u0000${entry.category}\u0000${entry.subcategory}\u0000${entry.account}`.toLowerCase().includes(needle);
    });
  }, [state, deferredSearch, filterType, filterAccount, filterCategory]);
  const selectedSet = useMemo(() => new Set(selectedIds), [selectedIds]);
  const selectedTotal = useMemo(() => {
    if (!state || selectedSet.size === 0) return 0;
    return state.entries.reduce((sum, entry) => selectedSet.has(entry.id) ? sum + (entry.type === 'expense' ? -entry.amount : entry.type === 'income' ? entry.amount : 0) : sum, 0);
  }, [state, selectedSet]);
  const toggleSelected = useCallback((entry: RedCoinsEntry) => setSelectedIds((ids) => ids.includes(entry.id) ? ids.filter((id) => id !== entry.id) : [...ids, entry.id]), []);

  if (!state) return <SafeAreaView style={s.loading}><Text style={s.loadingText}>Opening your money room…</Text></SafeAreaView>;

  const now = new Date(); const cycleStart = new Date(now.getFullYear(), now.getMonth() - (now.getDate() < state.payday ? 1 : 0), state.payday); const cycleRows = state.entries.filter((e) => new Date(e.date) >= cycleStart); const spent = cycleRows.filter((e) => e.type === 'expense').reduce((sum, e) => sum + e.amount, 0); const income = cycleRows.filter((e) => e.type === 'income').reduce((sum, e) => sum + e.amount, 0); const remaining = state.monthlyBudget - spent; const daysLeft = Math.max(1, Math.ceil((new Date(cycleStart.getFullYear(), cycleStart.getMonth() + 1, state.payday).getTime() - now.getTime()) / 86400000)); const cardDebt = state.accounts.filter((a) => a.type === 'Credit card').reduce((sum, a) => sum + Math.max(0, -a.balance), 0); const cash = state.accounts.filter((a) => ['Bank', 'Cash'].includes(a.type)).reduce((sum, a) => sum + a.balance, 0); const trueSpendable = Math.min(remaining - state.safetyBuffer, cash - cardDebt);
  const catSpend = cycleRows.filter((e) => e.type === 'expense').reduce<Record<string, number>>((map, e) => ({ ...map, [e.category]: (map[e.category] || 0) + e.amount }), {}); const topCats = Object.entries(catSpend).sort((a, b) => b[1] - a[1]);

  const Home = () => {
    const today = new Date();
    const weekDays = Array.from({ length: 7 }, (_, offset) => { const date = new Date(today); date.setDate(today.getDate() - (6 - offset)); const key = date.toISOString().slice(0, 10); return { key, label: date.toLocaleDateString('en-MY', { weekday: 'short' }), amount: state.entries.filter((e) => e.type === 'expense' && e.date.slice(0, 10) === key).reduce((sum, e) => sum + e.amount, 0) }; });
    const weekMax = Math.max(1, ...weekDays.map((day) => day.amount));
    const monthStartDate = new Date(today.getFullYear(), today.getMonth(), 1); const monthDays = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate(); const leading = monthStartDate.getDay();
    const calendar = Array.from({ length: leading + monthDays }, (_, index) => index < leading ? null : index - leading + 1);
    const months = Array.from({ length: 3 }, (_, offset) => { const date = new Date(today.getFullYear(), today.getMonth() - (2 - offset), 1); const prefix = date.toISOString().slice(0, 7); const rows = state.entries.filter((e) => e.date.startsWith(prefix)); return { label: date.toLocaleDateString('en-MY', { month: 'short' }), incoming: rows.filter((e) => e.type === 'income').reduce((sum, e) => sum + e.amount, 0), outgoing: rows.filter((e) => e.type === 'expense').reduce((sum, e) => sum + e.amount, 0) }; });
    const flowMax = Math.max(1, ...months.flatMap((month) => [month.incoming, month.outgoing]));
    return <>
      <View style={s.dashboardIntro}><View><Text style={s.eyebrow}>REDCOINS / SALARY CYCLE</Text><Text style={s.dashboardTitle}>Your money, clearly.</Text></View><Text style={s.dashboardDate}>{today.toLocaleDateString('en-MY', { day: 'numeric', month: 'short' })}</Text></View>
      <View style={s.dashCard}><Text style={s.dashHead}>Daily Summary</Text><View style={s.weekBars}>{weekDays.map((day) => <View key={day.key} style={s.weekDay}><Text style={s.weekAmount}>{day.amount ? `RM${day.amount.toFixed(0)}` : '0'}</Text><View style={[s.weekBar, { height: Math.max(3, day.amount / weekMax * 92) }]} /><Text style={s.weekLabel}>{day.label}</Text></View>)}</View><View style={s.summaryLine}><Text style={s.summaryMuted}>7 days average</Text><Text style={s.summaryExpense}>−{money(weekDays.reduce((sum, day) => sum + day.amount, 0) / 7)}</Text></View></View>
      <View style={s.dashCard}><View style={s.calendarHead}><Ionicons name="chevron-back" size={17} color={C.ink} /><Text style={s.dashHead}>{today.toLocaleDateString('en-MY', { month: 'long', year: 'numeric' })}</Text><Ionicons name="chevron-forward" size={17} color={C.ink} /></View><View style={s.calendarGrid}>{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((label) => <Text key={label} style={s.calendarWeek}>{label}</Text>)}{calendar.map((day, index) => <View key={index} style={[s.calendarDay, day === today.getDate() && s.calendarToday]}>{day && <><Text style={s.calendarNumber}>{day}</Text><View style={s.calendarDots}>{['expense','income','transfer'].map((kind) => state.entries.some((e) => e.type === kind && new Date(e.date).getFullYear() === today.getFullYear() && new Date(e.date).getMonth() === today.getMonth() && new Date(e.date).getDate() === day) ? <View key={kind} style={[s.calendarDot, { backgroundColor: kind === 'expense' ? C.coral : kind === 'income' ? '#18A879' : C.blue }]} /> : null)}</View></>}</View>)}</View></View>
      <View style={s.dashCard}><Text style={s.dashHead}>Budget Summary</Text><View style={s.budgetSummary}><View style={s.budgetRing}><View style={s.budgetRingInner}><Text style={s.budgetPct}>{Math.round(spent / Math.max(1, state.monthlyBudget) * 100)}%</Text><Text style={s.budgetSmall}>used</Text></View></View><View style={{ flex: 1 }}>{topCats.slice(0, 5).map(([name, value], index) => <View key={name} style={s.legendRow}><View style={[s.legendDot, { backgroundColor: [C.coral,C.blue,C.mint,C.gold,'#9B6BDD'][index] }]} /><Text style={s.legendName}>{name}</Text><Text style={s.legendValue}>{money(value)}</Text></View>)}</View></View><View style={s.budgetTrack}><View style={[s.budgetFill, { width: `${Math.min(100, spent / Math.max(1, state.monthlyBudget) * 100)}%` }]} /></View><View style={s.summaryLine}><Text style={s.summaryMuted}>EXPENSE</Text><Text style={s.summaryExpense}>{money(spent)} / {money(state.monthlyBudget)}</Text></View></View>
      <View style={s.dashCard}><Text style={s.dashHead}>Favorite Accounts</Text>{state.accounts.filter((a) => ['Bank','Cash','Credit card'].includes(a.type)).slice(0, 6).map((account) => <TouchableOpacity key={account.id} style={s.favoriteRow} onPress={() => setSection('accounts')}><Text style={s.favoriteName}>{account.name}</Text><Text style={[s.favoriteBalance, account.balance < 0 && { color: C.coral }]}>{account.balance < 0 ? '− ' : ''}{money(account.balance)}</Text></TouchableOpacity>)}<Text style={s.favoriteTotal}>Total: {money(state.accounts.filter((a) => ['Bank','Cash','Credit card'].includes(a.type)).reduce((sum, a) => sum + a.balance, 0))}</Text></View>
      <View style={s.dashCard}><Text style={s.dashHead}>Cash Flow</Text><View style={s.cashflowChart}>{months.map((month) => <View key={month.label} style={s.cashMonth}><View style={s.cashBars}><View style={[s.cashBar, { height: Math.max(3, month.outgoing / flowMax * 110), backgroundColor: C.coral }]} /><View style={[s.cashBar, { height: Math.max(3, month.incoming / flowMax * 110), backgroundColor: '#18A879' }]} /></View><Text style={s.weekLabel}>{month.label}</Text></View>)}</View></View>
      <View style={s.hero}><Text style={s.kicker}>TRUE SPENDABLE</Text><Text style={[s.heroMoney, trueSpendable < 0 && { color: '#FF8069' }]}>{trueSpendable < 0 ? '− ' : ''}{money(trueSpendable)}</Text><Text style={s.heroSub}>Budget left {money(remaining)} · cash after cards {money(cash - cardDebt)}</Text><View style={s.formula}><Mini label="CASH" value={cash} /><Mini label="CARD OWED" value={-cardDebt} /><Mini label="SAFE/DAY" value={Math.max(0, remaining) / daysLeft} /></View></View>
    </>;
  };
  const activityHeader = <View><Title eyebrow="TRANSACTION LEDGER" title={selectedIds.length ? `${selectedTotal < 0 ? '− ' : '+ '}${money(selectedTotal)} selected` : 'Everything that moved.'} />
    <View style={s.ledgerTools}><TextInput value={search} onChangeText={setSearch} placeholder="Search item, category, account…" placeholderTextColor={C.muted} style={[s.search, { flex: 1 }]} /><TouchableOpacity style={s.filterButton} onPress={() => setFilterOpen(true)}><Ionicons name="options" size={19} color={C.white} /></TouchableOpacity></View>
    {selectedIds.length > 0 && <View style={s.selectionBar}><Text style={s.selectionCount}>{selectedIds.length} selected</Text><TouchableOpacity onPress={() => setSelectedIds(filtered.map((e) => e.id))}><Text style={s.selectionLink}>SELECT ALL</Text></TouchableOpacity><TouchableOpacity onPress={() => setSelectedIds([])}><Text style={s.selectionLink}>CLOSE</Text></TouchableOpacity></View>}
  </View>;
  const filterModal = <Modal visible={filterOpen} transparent animationType="slide" onRequestClose={() => setFilterOpen(false)}><View style={s.sheetShade}><View style={s.selectionSheet}><View style={s.sheetGrab} /><Text style={s.sheetTitle}>Filter transactions</Text><Text style={s.inputLabel}>TYPE</Text><View style={s.typeRow}>{(['all', 'expense', 'income', 'transfer'] as const).map((x) => <Chip key={x} text={x.toUpperCase()} active={filterType === x} onPress={() => setFilterType(x)} />)}</View><Text style={s.inputLabel}>ACCOUNT</Text><ScrollView horizontal>{['all', ...state.accounts.map((a) => a.name)].map((x) => <Chip key={x} text={x} active={filterAccount === x} onPress={() => setFilterAccount(x)} />)}</ScrollView><Text style={s.inputLabel}>CATEGORY</Text><ScrollView horizontal>{['all', ...state.categories.map((c) => c.name)].map((x) => <Chip key={x} text={x} active={filterCategory === x} onPress={() => setFilterCategory(x)} />)}</ScrollView><TouchableOpacity style={s.sheetSave} onPress={() => setFilterOpen(false)}><Text style={s.sheetSaveText}>APPLY FILTERS</Text></TouchableOpacity></View></View></Modal>;
  const Accounts = () => { const pending = state.entries.filter((e) => e.origin === 'redcoins' && !e.exportedAt); const awaiting = [...(state.exportBatches || [])].reverse().find((batch) => !batch.confirmedAt); const runExport = async (mode: 'pending' | 'all') => { const batch = await exportRedCoinsCsv(state, mode); if (!batch) return Alert.alert('Nothing new to export', 'Every RedCoins entry is already marked as imported.'); await persist({ ...state, exportBatches: [batch, ...(state.exportBatches || [])] }); }; return <><Title eyebrow="MONEY LIBRARY" title="Your structure, your rules." action="＋ Account" onAction={() => { setDraftName(''); setDraftBalance('0'); setManageOpen('account'); }} /><View style={s.accountGrid}>{state.accounts.map((a) => <View key={a.id} style={[s.accountCard, a.type === 'Credit card' && s.dark]}><Text style={s.accountType}>{a.type.toUpperCase()}</Text><Text style={[s.accountName, a.type === 'Credit card' && { color: C.paper }]}>{a.name}</Text><Text style={[s.accountBalance, a.balance < 0 && { color: '#FF8069' }]}>{a.balance < 0 ? '− ' : ''}{money(a.balance)}</Text></View>)}</View><Title eyebrow="CATEGORIES" title="Built around your life." action="＋ Category" onAction={() => { setDraftCategory(''); setDraftSub(''); setManageOpen('category'); }} />{state.categories.map((c) => <View key={c.id} style={s.categoryCard}><View style={{ flex: 1 }}><Text style={s.categoryName}>{c.icon} {c.name}</Text><Text style={s.categorySubs}>{c.subcategories.join(' · ')}</Text></View><TouchableOpacity onPress={() => { setDraftParent(c.name); setDraftSub(''); setManageOpen('sub'); }} style={s.smallButton}><Text style={s.smallButtonText}>＋ SUB</Text></TouchableOpacity></View>)}<Title eyebrow="AUTOMATION" title="What comes back." /><View style={s.card}>{state.entries.filter((e) => e.repeat && e.repeat !== 'none').slice(0, 8).map((e) => <EntryRow key={e.id} entry={e} />)}{!state.entries.some((e) => e.repeat && e.repeat !== 'none') && <Empty text="No scheduled RedCoins entries yet." />}</View><Title eyebrow="DATA BRIDGE" title="RedCoins → Bluecoins." /><View style={s.exportCard}><Text style={s.exportTitle}>Weekly hand-off</Text><Text style={s.exportCopy}>{pending.length} new entries since the last confirmed import. Bluecoins baseline history is never exported again.</Text><TouchableOpacity style={s.exportPrimary} onPress={() => runExport('pending')}><Text style={s.exportPrimaryText}>EXPORT {pending.length} NEW ENTRIES</Text></TouchableOpacity>{awaiting && <TouchableOpacity style={s.confirmImport} onPress={async () => persist(confirmRedCoinsExport(state, awaiting.id))}><Ionicons name="checkmark-circle" size={17} color={C.ink} /><Text style={s.confirmImportText}>MARK {awaiting.entryIds.length} AS IMPORTED</Text></TouchableOpacity>}<TouchableOpacity style={s.exportSecondary} onPress={() => runExport('all')}><Text style={s.exportSecondaryText}>EXPORT ALL REDCOINS ENTRIES</Text></TouchableOpacity><TouchableOpacity style={s.exportSecondary} onPress={() => exportRedCoinsBackup(state)}><Text style={s.exportSecondaryText}>BACKUP REDCOINS</Text></TouchableOpacity></View><Title eyebrow="EXPORT HISTORY" title="What crossed over." /><View style={s.card}>{(state.exportBatches || []).slice(0, 6).map((batch) => <View key={batch.id} style={s.commitRow}><View><Text style={s.entryName}>{batch.entryIds.length} entries</Text><Text style={s.entryMeta}>{new Date(batch.createdAt).toLocaleString('en-MY')}</Text></View><Text style={[s.exportStatus, batch.confirmedAt && { color: '#379B73' }]}>{batch.confirmedAt ? 'IMPORTED' : 'AWAITING'}</Text></View>)}{!state.exportBatches?.length && <Empty text="No export batches yet." />}</View><Title eyebrow="RECOVERY" title="Trash." /> <View style={s.card}>{state.trash.map((entry) => <View key={entry.id} style={s.trashRow}><View style={{ flex: 1 }}><Text style={s.entryName}>{entry.item}</Text><Text style={s.entryMeta}>{money(entry.amount)} · {entry.date.slice(0,10)}</Text></View><TouchableOpacity style={s.restoreButton} onPress={async () => { const next = { ...state, trash: state.trash.filter((e) => e.id !== entry.id), entries: [entry, ...state.entries], accounts: state.accounts.map((a) => ({ ...a })) }; applyEntryBalance(next, entry, 1); await persist(next); }}><Text style={s.restoreText}>RESTORE</Text></TouchableOpacity></View>)}{!state.trash.length && <Empty text="Trash is empty." />}</View></>; };
  const Plan = () => <><Title eyebrow="SALARY-CYCLE PLAN" title="Give every ringgit a job." /><View style={s.planHero}><PlanCell label="CYCLE SPEND" value={spent} /><PlanCell label="REMAINING" value={remaining} /><PlanCell label="PROJECTED" value={spent / Math.max(1, new Date().getDate()) * 30} /></View><View style={s.card}><Text style={s.cardTitle}>Cash reality</Text><Text style={[s.realityNumber, trueSpendable < 0 && { color: C.coral }]}>{trueSpendable < 0 ? '− ' : ''}{money(trueSpendable)}</Text><View style={s.grid}><Mini label="LIQUID" value={cash} /><Mini label="CARD OWED" value={-cardDebt} /><Mini label="BUFFER" value={-state.safetyBuffer} /></View></View><View style={s.card}><Text style={s.cardTitle}>Plan controls</Text><Field label="MONTHLY BUDGET" value={String(state.monthlyBudget)} onChange={async (v: string) => persist({ ...state, monthlyBudget: Number(v) || 0 })} numeric /><Field label="PAYDAY (1—28)" value={String(state.payday)} onChange={async (v: string) => persist({ ...state, payday: Math.max(1, Math.min(28, Number(v) || 25)) })} numeric /><Field label="SAFETY BUFFER" value={String(state.safetyBuffer)} onChange={async (v: string) => persist({ ...state, safetyBuffer: Number(v) || 0 })} numeric /></View><Title eyebrow="FIXED COMMITMENTS" title="Expected before payday." /><View style={s.card}>{bluecoins?.monthly.fixedCommitments.items.map((item) => <View key={item.name} style={s.commitRow}><View><Text style={s.entryName}>{item.name}</Text><Text style={s.entryMeta}>{item.transactions} transaction{item.transactions === 1 ? '' : 's'}</Text></View><Text style={s.entryAmount}>{money(item.amount)}</Text></View>)}{!bluecoins?.monthly.fixedCommitments.items.length && <Empty text="No fixed commitments detected." />}</View><Title eyebrow="SPENDING GUARDS" title="Boundaries before regret." /><View style={s.ruleGrid}>{bluecoins?.spendingGuards.map((guard) => <View key={guard.id} style={[s.ruleCard, guard.level === 'danger' && { borderColor: C.coral }]}><Text style={s.accountType}>{guard.scope.toUpperCase()}</Text><Text style={s.ruleName}>{guard.name}</Text><Text style={s.rulePct}>{guard.percent.toFixed(0)}%</Text><Text style={s.entryMeta}>{money(guard.spent)} / {money(guard.limit)}</Text><View style={s.budgetTrack}><View style={[s.budgetFill, { width: `${Math.min(100, guard.percent)}%` }]} /></View></View>)}</View></>;
  const Reports = () => <><Title eyebrow="REPORTS" title="Patterns, not vibes." /><View style={s.grid}><Stat label="INCOME" value={income} color={C.mint} /><Stat label="EXPENSE" value={spent} color={C.coral} /><Stat label="NET" value={income - spent} color={C.blue} /></View><View style={s.card}><Text style={s.cardTitle}>Top categories · salary cycle</Text>{topCats.map(([name, value], index) => <View key={name} style={s.reportRow}><Text style={s.reportName}>{index + 1}. {name}</Text><View style={s.reportTrack}><View style={[s.reportFill, { width: `${spent ? Math.min(100, value / spent * 100) : 0}%` }]} /></View><Text style={s.reportValue}>{money(value)}</Text></View>)}{!topCats.length && <Empty text="Reports wake up after your first expense." />}</View></>;

  return <SafeAreaView style={s.safe}><View style={s.header}><TouchableOpacity onPress={() => navigation.navigate('Home')} style={s.back}><Ionicons name="arrow-back" size={21} color={C.ink} /></TouchableOpacity><View style={{ flex: 1 }}><Text style={s.brand}>REDCOINS</Text><Text style={s.source}>{state.importedSource ? `Structure seeded from ${state.importedSource}` : 'LeanLog money room'}</Text></View><TouchableOpacity style={s.headerAdd} onPress={resetEntry}><Ionicons name="add" size={24} color={C.white} /></TouchableOpacity></View>
    {section === 'activity' ? <View style={s.activityBody}>{activityHeader}<View style={[s.card, s.ledgerCard]}><FlatList
      data={filtered}
      keyExtractor={(entry) => entry.id}
      renderItem={({ item: entry }) => <EntryRow entry={entry} selected={selectedSet.has(entry.id)} onPress={selectedIds.length ? () => toggleSelected(entry) : undefined} onLong={() => toggleSelected(entry)} />}
      extraData={selectedIds}
      initialNumToRender={16}
      maxToRenderPerBatch={16}
      updateCellsBatchingPeriod={32}
      windowSize={7}
      removeClippedSubviews
      keyboardShouldPersistTaps="always"
      keyboardDismissMode="on-drag"
      ListEmptyComponent={<Empty text="No matching RedCoins entries." />}
      showsVerticalScrollIndicator={false}
      contentContainerStyle={!filtered.length ? s.emptyLedger : undefined}
    /></View></View> : <ScrollView contentContainerStyle={s.body} showsVerticalScrollIndicator={false}>{section === 'home' ? <Home /> : section === 'accounts' ? <Accounts /> : section === 'plan' ? <Plan /> : <Reports />}</ScrollView>}
    {filterModal}<View style={s.nav}>{(['home', 'activity', 'accounts', 'plan', 'reports'] as Section[]).map((name) => <TouchableOpacity key={name} style={[s.navButton, section === name && s.navActive]} onPress={() => setSection(name)}><Ionicons name={({ home: 'grid', activity: 'list', accounts: 'wallet', plan: 'shield-checkmark', reports: 'bar-chart' } as any)[name]} size={18} color={section === name ? C.white : '#8993A6'} /><Text style={[s.navText, section === name && { color: C.white }]}>{name[0].toUpperCase() + name.slice(1)}</Text></TouchableOpacity>)}</View>
    <EntryModal visible={entryOpen} close={() => setEntryOpen(false)} {...{ item, setItem, amount, setAmount, type, setType, account, setAccount, toAccount, setToAccount, category, setCategory, subcategory, setSubcategory, note, setNote, labels, setLabels, repeat, setRepeat, installments, setInstallments, advanced, setAdvanced, suggestions, chooseSuggestion, saveEntry, state }} />
    <ManageModal visible={!!manageOpen} mode={manageOpen} close={() => setManageOpen(null)} state={state} draft={{ draftName, setDraftName, draftType, setDraftType, draftBalance, setDraftBalance, draftCategory, setDraftCategory, draftSub, setDraftSub, draftParent }} save={async () => { const next = { ...state, accounts: [...state.accounts], categories: state.categories.map((c) => ({ ...c, subcategories: [...c.subcategories] })) }; if (manageOpen === 'account') { if (!draftName.trim()) return; next.accounts.push({ id: `${Date.now()}`, name: draftName.trim(), type: draftType, balance: Number(draftBalance) || 0 }); } else if (manageOpen === 'category') { if (!draftCategory.trim() || !draftSub.trim()) return; next.categories.push({ id: `${Date.now()}`, name: draftCategory.trim(), icon: '●', subcategories: [draftSub.trim()] }); } else { const parent = next.categories.find((c) => c.name === draftParent); if (!parent || !draftSub.trim()) return; parent.subcategories.push(draftSub.trim()); } await persist(next); setManageOpen(null); }} />
  </SafeAreaView>;
}

function Title({ eyebrow, title, action, onAction }: any) { return <View style={s.titleRow}><View style={{ flex: 1 }}><Text style={s.eyebrow}>{eyebrow}</Text><Text style={s.title}>{title}</Text></View>{action && <TouchableOpacity style={s.titleAction} onPress={onAction}><Text style={s.titleActionText}>{action}</Text></TouchableOpacity>}</View>; }
function Mini({ label, value }: any) { return <View style={s.mini}><Text style={s.miniValue}>{value < 0 ? '− ' : ''}{money(value)}</Text><Text style={s.miniLabel}>{label}</Text></View>; }
function Stat({ label, value, color }: any) { return <View style={s.stat}><Text style={s.statLabel}>{label}</Text><Text style={[s.statValue, { color }]}>{value < 0 ? '− ' : ''}{money(value)}</Text></View>; }
function PlanCell({ label, value }: any) { return <View style={s.planCell}><Text style={s.planLabel}>{label}</Text><Text style={s.planValue}>{value < 0 ? '− ' : ''}{money(value)}</Text></View>; }
function Empty({ text }: any) { return <Text style={s.empty}>{text}</Text>; }
const EntryRow = memo(function EntryRow({ entry, onLong, onPress, selected }: { entry: RedCoinsEntry; onLong?: () => void; onPress?: () => void; selected?: boolean }) { const color = entry.type === 'transfer' ? C.blue : entry.type === 'income' ? '#18A879' : C.coral; return <TouchableOpacity onPress={onPress} onLongPress={onLong} style={[s.entry, selected && { backgroundColor: '#E3E2F7', marginHorizontal: -8, paddingHorizontal: 8 }]}><View style={[s.entryIcon, { backgroundColor: color }]}>{selected ? <Ionicons name="checkmark" size={18} color={C.white} /> : <Ionicons name={entry.type === 'transfer' ? 'swap-horizontal' : entry.type === 'income' ? 'arrow-down' : 'arrow-up'} size={17} color={C.white} />}</View><View style={{ flex: 1 }}><Text style={s.entryName}>{entry.item}</Text><Text style={s.entryMeta}>{entry.type === 'transfer' ? `${entry.account} → ${entry.toAccount || 'Unknown'}` : `${entry.subcategory} · ${entry.account}`}</Text></View><Text style={[s.entryAmount, { color }]}>{entry.type === 'income' ? '+' : entry.type === 'transfer' ? '⇄ ' : '− '}{money(entry.amount)}</Text></TouchableOpacity>; });
function Field({ label, value, onChange, numeric }: any) { return <View style={s.field}><Text style={s.fieldLabel}>{label}</Text><TextInput value={value} onChangeText={onChange} keyboardType={numeric ? 'numeric' : 'default'} style={s.fieldInput} /></View>; }

function EntryModal(p: any) {
  const [picker, setPicker] = useState<'account' | 'destination' | 'category' | null>(null);
  const [pickerSearch, setPickerSearch] = useState('');
  const cats = p.state.categories;
  const openPicker = (value: typeof picker) => { setPickerSearch(''); setPicker(value); };
  return <Modal visible={p.visible} animationType="slide" onRequestClose={p.close}>
    <SafeAreaView style={s.modal}>
      <View style={s.modalHead}><TouchableOpacity onPress={p.close}><Ionicons name="arrow-back" size={24} color={C.ink} /></TouchableOpacity><Text style={s.modalTitle}>New entry</Text><Text style={s.plusOne}>+1</Text></View>
      <ScrollView contentContainerStyle={s.modalBody} keyboardShouldPersistTaps="handled">
        <View style={s.typeRow}>{(['expense', 'income', 'transfer'] as RedCoinsType[]).map((x) => <TouchableOpacity key={x} onPress={() => p.setType(x)} style={[s.typeButton, p.type === x && { backgroundColor: x === 'expense' ? C.coral : x === 'income' ? '#379B73' : C.blue }]}><Text style={[s.typeText, p.type === x && { color: C.white }]}>{x.toUpperCase()}</Text></TouchableOpacity>)}</View>
        <TextInput style={s.itemInput} value={p.item} onChangeText={p.setItem} placeholder="Name" placeholderTextColor="#AAA393" />
        {p.suggestions.length > 0 && <View style={s.suggestions}>{p.suggestions.map((x: any) => <TouchableOpacity key={x.id} onPress={() => p.chooseSuggestion(x)} style={s.suggestion}><View><Text style={s.suggestionName}>{x.item}</Text><Text style={s.suggestionMeta}>{x.category} · {x.subcategory} · {x.account}</Text></View><Text style={s.suggestionPrice}>{money(x.amount)}</Text></TouchableOpacity>)}</View>}
        <Text style={s.entryDate}>{new Date().toLocaleString('en-MY', { dateStyle: 'medium', timeStyle: 'short' })}</Text>
        <View style={s.amountWrap}><View style={[s.amountSign, { backgroundColor: p.type === 'expense' ? C.coral : p.type === 'income' ? '#379B73' : C.blue }]}><Text style={s.amountSignText}>{p.type === 'expense' ? '−' : p.type === 'income' ? '+' : '⇄'}</Text></View><TextInput style={s.amountBare} value={p.amount} onChangeText={p.setAmount} keyboardType="decimal-pad" placeholder="0.00" placeholderTextColor="#AAA393" /><Text style={s.currency}>MYR</Text></View>
        {p.type !== 'transfer' && <PickerRow icon="grid-outline" label="CATEGORY" value={`${cats.find((c: any) => c.name === p.category)?.icon || '●'}  ${p.subcategory || p.category}`} onPress={() => openPicker('category')} />}
        <PickerRow icon="wallet-outline" label={p.type === 'transfer' ? 'FROM ACCOUNT' : 'ACCOUNT'} value={p.account || 'Choose account'} onPress={() => openPicker('account')} />
        {p.type === 'transfer' && <PickerRow icon="arrow-forward-circle-outline" label="TRANSFER TO" value={p.toAccount || 'Choose destination'} onPress={() => openPicker('destination')} />}
        <TouchableOpacity style={s.advancedButton} onPress={() => p.setAdvanced(!p.advanced)}><Text style={s.advancedText}>Split · Status · Labels · Repeat</Text><Ionicons name={p.advanced ? 'chevron-up' : 'chevron-down'} size={17} color={C.muted} /></TouchableOpacity>
        {p.advanced && <View style={s.advancedBox}><Field label="LABELS" value={p.labels} onChange={p.setLabels} /><Text style={s.inputLabel}>REPEAT</Text><View style={s.typeRow}>{['none', 'weekly', 'monthly', 'installment'].map((x) => <TouchableOpacity key={x} onPress={() => p.setRepeat(x)} style={[s.repeatButton, p.repeat === x && s.repeatActive]}><Text style={s.repeatText}>{x}</Text></TouchableOpacity>)}</View>{p.repeat === 'installment' && <Field label="NUMBER OF INSTALMENTS" value={p.installments} onChange={p.setInstallments} numeric />}</View>}
        <TextInput style={s.noteInput} value={p.note} onChangeText={p.setNote} placeholder="Note" placeholderTextColor={C.muted} multiline />
      </ScrollView>
      <View style={s.entryFooter}><TouchableOpacity style={[s.entrySave, { backgroundColor: p.type === 'expense' ? C.coral : p.type === 'income' ? '#379B73' : C.blue }]} onPress={p.saveEntry}><Ionicons name="save-outline" size={21} color="#FFF" /><Text style={s.entrySaveText}>SAVE {p.type.toUpperCase()}</Text></TouchableOpacity></View>
      <SelectionSheet visible={!!picker} close={() => setPicker(null)} search={pickerSearch} setSearch={setPickerSearch} title={picker === 'category' ? 'Choose category' : picker === 'destination' ? 'Transfer to' : 'Choose account'}>
        {picker === 'category' ? cats.map((group: any) => { const matches = group.subcategories.filter((sub: string) => `${group.name} ${sub}`.toLowerCase().includes(pickerSearch.toLowerCase())); return matches.length ? <View key={group.id}><Text style={s.pickerGroup}>{group.name}</Text><View style={s.categoryGrid}>{matches.map((sub: string) => <TouchableOpacity key={sub} style={s.categoryChoice} onPress={() => { p.setCategory(group.name); p.setSubcategory(sub); setPicker(null); }}><View style={s.categoryIcon}><Text>{group.icon}</Text></View><Text style={s.categoryChoiceText}>{sub}</Text></TouchableOpacity>)}</View></View> : null; }) : p.state.accounts.filter((a: any) => a.name.toLowerCase().includes(pickerSearch.toLowerCase()) && (picker !== 'destination' || a.name !== p.account)).map((a: any) => <TouchableOpacity key={a.id} style={s.accountChoice} onPress={() => { picker === 'destination' ? p.setToAccount(a.name) : p.setAccount(a.name); setPicker(null); }}><View><Text style={s.accountChoiceName}>{a.name}</Text><Text style={s.accountChoiceType}>{a.type}</Text></View><Text style={[s.accountChoiceBalance, a.balance < 0 && { color: C.coral }]}>{a.balance < 0 ? '− ' : ''}{money(a.balance)}</Text></TouchableOpacity>)}
      </SelectionSheet>
    </SafeAreaView>
  </Modal>;
}
function PickerRow({ icon, label, value, onPress }: any) { return <TouchableOpacity style={s.pickerRow} onPress={onPress}><View style={s.pickerRowIcon}><Ionicons name={icon} size={19} color={C.ink} /></View><View style={{ flex: 1 }}><Text style={s.pickerRowLabel}>{label}</Text><Text style={s.pickerRowValue}>{value}</Text></View><Ionicons name="chevron-forward" size={18} color={C.muted} /></TouchableOpacity>; }
function SelectionSheet({ visible, close, search, setSearch, title, children }: any) { return <Modal visible={visible} transparent animationType="slide" onRequestClose={close}><View style={s.sheetShade}><View style={s.selectionSheet}><View style={s.sheetGrab} /><View style={s.selectionTop}><TextInput value={search} onChangeText={setSearch} placeholder={`Search ${title.toLowerCase()}…`} placeholderTextColor={C.muted} style={s.selectionSearch} /><TouchableOpacity style={s.selectionDone} onPress={close}><Text style={s.selectionDoneText}>DONE</Text></TouchableOpacity></View><ScrollView keyboardShouldPersistTaps="handled">{children}</ScrollView></View></View></Modal>; }
function Chip({ text, active, onPress }: any) { return <TouchableOpacity onPress={onPress} style={[s.chip, active && s.chipActive]}><Text style={[s.chipText, active && { color: C.white }]}>{text}</Text></TouchableOpacity>; }
function ManageModal({ visible, mode, close, draft, save }: any) { return <Modal visible={visible} transparent animationType="slide" onRequestClose={close}><Pressable style={s.sheetShade} onPress={close}><Pressable style={s.sheet} onPress={() => {}}><View style={s.sheetGrab} /><Text style={s.eyebrow}>{mode === 'account' ? 'NEW ACCOUNT' : mode === 'category' ? 'NEW CATEGORY' : 'NEW SUBCATEGORY'}</Text><Text style={s.sheetTitle}>{mode === 'account' ? 'Add your money container' : mode === 'category' ? 'Name the spending' : `Add to ${draft.draftParent}`}</Text>{mode === 'account' ? <><Field label="ACCOUNT NAME" value={draft.draftName} onChange={draft.setDraftName} /><Text style={s.inputLabel}>TYPE</Text><View style={s.typeRow}>{(['Bank', 'Cash', 'Credit card', 'Liability', 'Investment'] as RedCoinsAccountType[]).map((x) => <TouchableOpacity key={x} onPress={() => draft.setDraftType(x)} style={[s.repeatButton, draft.draftType === x && s.repeatActive]}><Text style={s.repeatText}>{x}</Text></TouchableOpacity>)}</View><Field label="OPENING BALANCE" value={draft.draftBalance} onChange={draft.setDraftBalance} numeric /></> : mode === 'category' ? <><Field label="CATEGORY" value={draft.draftCategory} onChange={draft.setDraftCategory} /><Field label="FIRST SUBCATEGORY" value={draft.draftSub} onChange={draft.setDraftSub} /></> : <Field label="SUBCATEGORY" value={draft.draftSub} onChange={draft.setDraftSub} />}<TouchableOpacity style={s.sheetSave} onPress={save}><Text style={s.sheetSaveText}>SAVE</Text></TouchableOpacity></Pressable></Pressable></Modal>; }

